declare var React;
declare var $;
declare var ReactDOM;

let ErrorService = React.createClass({
    getInitialState: function() {
        this._selectedErrorInfos = [];
        this._origin = location.origin;
        this._errorMap = [];
        this._errorKeys = [];
        this._currentErrorServiceErrorId = "";
        this._priorityQueueErrors = [];
        this._reschedulerErrors = [];

        this.getErrorCodeData();

        // set the render method to update on an interval so we can update the dom based on the connectivity state of the socket
        setInterval(()=>{
            ReactDOM.render(this.render(), document.getElementById('error-service'));
        }, 1000);

        return {};
    },

    getCurrentErrorServiceError() {
        let getCurrentErrorIdUrl = this._origin + '/getCurrentErrorId';
        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", getCurrentErrorIdUrl, true);
        request.onreadystatechange = () => {
            // request is complete
            if(request.readyState === 4) {
                // "OK" status
                if(request.status === 200) {
                    let response = JSON.parse(request.response);
                    this._currentErrorServiceErrorId = response.currentErrorId;
                } else {
                    console.error("cannot get current error id data");
                }
            }
        };
        request.send();
    },

    getErrorCodeData() {
        let errorCodeDataUrl = this._origin + '/errorCodeData';
        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", errorCodeDataUrl, true);
        request.onreadystatechange = () => {
            // request is complete
            if(request.readyState === 4) {
                // "OK" status
                if(request.status === 200) {
                    let response = JSON.parse(request.response);

                    this._errorMap = response.errorList;
                    this._errorKeys = Object.keys(this._errorMap);
                    this._errorKeys.sort();
                } else {
                    console.error("cannot get error code data");
                }
            }
        };
        request.send();
    },

    getErrorServiceContents() {
        let getContentsUrl = this._origin + '/getContents';
        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", getContentsUrl, true);
        request.onreadystatechange = () => {
            // request is complete
            if(request.readyState === 4) {
                // "OK" status
                if(request.status === 200) {
                    let response = JSON.parse(request.response);

                    let priorityQueueJSONArray = JSON.parse(response.priorityQueueErrors);
                    this._priorityQueueErrors = [];
                    for(let i = 0; i < priorityQueueJSONArray.length; ++i) {
                        let errorInfo = priorityQueueJSONArray[i];
                        let errorInfoPre = <pre id={errorInfo._id} key={errorInfo._id}>{JSON.stringify(errorInfo, null, 4)}</pre>;

                        this._priorityQueueErrors.push(errorInfoPre);
                    }

                    let reschedulerJSONArray = JSON.parse(response.reschedulerErrors);
                    this._reschedulerErrors = [];
                    for(let i = 0; i < reschedulerJSONArray.length; ++i) {
                        let errorInfo = reschedulerJSONArray[i];
                        let errorInfoPre = <pre id={errorInfo._id} key={errorInfo._id}>{JSON.stringify(errorInfo, null, 4)}</pre>;

                        this._reschedulerErrors.push(errorInfoPre);
                    }
                } else {
                    console.error("cannot get priority queue data");
                }
            }
        };
        request.send();
    },

    sendMockCodes(enabled) {
        // TODO: eventually this will need to be an array of ints to mimic what we would actually be sending the platform side.
        // this is currently blocked by not having a mapping of error string to int on the SSM side
        let activeErrorArray = [];
        let node = document.getElementById("right");
        for (let i = 0; i < node.childNodes.length; ++i) {
            let optionNode = node.childNodes[i] as HTMLOptionElement;
            activeErrorArray.push(optionNode.id);
        }

        // request the data for the system monitoring service
        let mockCodesUrl = this._origin + '/mockErrorCodes';
        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", mockCodesUrl, true);
        request.send(JSON.stringify({
            enabled: enabled,
            codes: activeErrorArray
        }));
    },

    sortById(a, b) {
        let aId = (typeof a.hasAttribute === "function") && a.hasAttribute('id') ? a.id : a.props.id;
        let bId = (typeof b.hasAttribute === "function") && b.hasAttribute('id') ? b.id : b.props.id;
        return aId.localeCompare(bId);
    },

    moveRight() {
        let node = document.getElementById("left");
        for (let i = 0; i < node.childNodes.length; i++) {
            let optionNode = node.childNodes[i] as HTMLOptionElement;
            if (optionNode.selected) {
                document.getElementById("right").appendChild(optionNode.cloneNode(true));
                node.removeChild(optionNode);
                --i;
            }
        }
        let sortedErrors = $("#right").children().sort(this.sortById);
        $("#right").html(sortedErrors);
        this.selectError();

        let errorsEnabled = sortedErrors.length > 0;
        this.sendMockCodes(errorsEnabled);
    },

    moveLeft() {
        let node = document.getElementById("right");
        for (let i = 0; i < node.childNodes.length; i++) {
            let optionNode = node.childNodes[i] as HTMLOptionElement;
            if (optionNode.selected) {
                document.getElementById("left").appendChild(optionNode.cloneNode(true));
                node.removeChild(optionNode);
                --i;
            }
        }
        let sortedErrors = $("#left").children().sort(this.sortById);
        $("#left").html(sortedErrors);
        this.selectError();

        let errorsEnabled = node.childNodes.length > 0;
        this.sendMockCodes(errorsEnabled);
    },

    moveAllRight() {
        let node = document.getElementById("left");
        while (node.childNodes.length > 0) {
            document.getElementById("right").appendChild(node.firstChild.cloneNode(true));
            node.removeChild(node.firstChild);
        }
        let sortedErrors = $("#right").children().sort(this.sortById);
        $("#right").html(sortedErrors);
        this.selectError();

        let errorsEnabled = sortedErrors.length > 0;
        this.sendMockCodes(errorsEnabled);
    },

    moveAllLeft() {
        let node = document.getElementById("right");
        while (node.childNodes.length > 0) {
            document.getElementById("left").appendChild(node.firstChild.cloneNode(true));
            node.removeChild(node.firstChild);
        }
        let sortedErrors = $("#left").children().sort(this.sortById);
        $("#left").html(sortedErrors);
        this.selectError();

        let errorsEnabled = node.childNodes.length > 0;
        this.sendMockCodes(errorsEnabled);
    },

    updateErrorServiceInfo() {
        this.getCurrentErrorServiceError();
        this.getErrorServiceContents();
    },

    render() {
        let errorCodeOptions = [];

        this._errorKeys.sort();
        for(let i = 0; i < this._errorKeys.length; ++i) {
            let error = this._errorKeys[i];
            errorCodeOptions.push(<option id={error} key={error}>{error}</option>);
        }

        let renderHtml = <div>
            <h1>Error Service Debug Page</h1>
            <label>
                <input type="checkbox" onChange={this.disableSkillSwitch}/>Disable error service skill switch
                <br/>
                <input type="button" onClick={this.updateErrorServiceInfo} value="Refresh"/>
            </label>
            <table>
                <tbody>
                    <tr>
                        <td>
                            <text>Error List</text>
                            <br/>
                            <select multiple="multiple" id="left" style={{height: 500, width: 300}} onChange={this.selectError}>
                                {errorCodeOptions}
                            </select>
                        </td>
                        <td>
                            <input type="button" value="<" onClick={this.moveLeft}/>
                            <input type="button" value="<<" onClick={this.moveAllLeft}/>
                            <input type="button" value=">>" onClick={this.moveAllRight}/>
                            <input type="button" value=">" onClick={this.moveRight}/>
                        </td>
                        <td>
                            <text>Active Errors</text>
                            <br/>
                            <select multiple="multiple" id="right" style={{height: 500, width: 300}} onChange={this.selectError}></select>
                        </td>
                    </tr>
                </tbody>
            </table>

            <div id="current-error">
                <text><h3>Current Error Service Error:</h3>{this._currentErrorServiceErrorId}</text>
            </div>
            <div id="priority-queue-errors">
                <text><h3>Current Priority Queue Errors:</h3>{this._priorityQueueErrors}</text>
            </div>
            <div id="rescheduler-errors">
                <text><h3>Rescheduler Errors:</h3>{this._reschedulerErrors}</text>
            </div>

            <div id="error-info">
                <text><h2>Error Info</h2></text>
                { this._selectedErrorInfos }
            </div>
        </div>;

        return renderHtml;
    },

    selectError() {
        this._selectedErrorInfos = [];

        let errorInfoTextArea = $("#error-info");
        errorInfoTextArea.innerHTML = "";

        this.displayErrorInfoForSelectedElements(document.getElementById("left"));
        this.displayErrorInfoForSelectedElements(document.getElementById("right"));

        this._selectedErrorInfos.sort(this.sortById);
    },

    disableSkillSwitch(event) {
        let isChecked = event.target.checked;

        let disableSkillSwitchingUrl = this._origin + '/disableSkillSwitching';
        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", disableSkillSwitchingUrl, true);
        request.send(JSON.stringify({
            disabled: isChecked,
        }));
    },

    displayErrorInfoForSelectedElements(node) {
        for (let i = 0; i < node.childNodes.length; i++) {
            let optionNode = node.childNodes[i] as HTMLOptionElement;
            if (optionNode.selected) {
                let errorInfo = this._errorMap[optionNode.id];
                let errorInfoPre = <pre id={errorInfo._id} key={errorInfo._id}>{JSON.stringify(errorInfo, null, 4)}</pre>;
                this._selectedErrorInfos.push(errorInfoPre);
            }
        }
    }
});

$(document).ready(() => {
    // the error service needs to be started first so it can receive the message for which port the system-monitoring-service-sim is being hosted
    ReactDOM.render(<ErrorService/>, document.getElementById('error-service'));
});
